return (
        self.major in [
            'robotics', 'computer_science', 'electrical_engineering',
            'mechanical_engineering', 'software_engineering', 'engineering'
        ]
        and self.education in ['bachelor', 'master', 'doctor']
        and self.technical_aptitude in ['excellent', 'good', 'high', 'very_high']
)

suitable_majors = {
            'robotics', 'computer_science', 'electrical_engineering',
            'mechanical_engineering', 'engineering', 'software_engineering',
            'data_science', 'physics', 'mathematics'
        }

        suitable_education_levels = {
            'bachelor', 'master', 'doctor'
        }

        suitable_technical_aptitudes = {
            'excellent', 'good', 'high', 'very_high'
        }

        has_relevant_major = self.major in suitable_majors
        has_sufficient_education = self.education in suitable_education_levels
        has_strong_technical_aptitude = self.technical_aptitude in suitable_technical_aptitudes

        return has_relevant_major and has_sufficient_education and has_strong_technical_aptitude
